private ListenableFutureTask<Bitmap> get() {
  Util.assertMainThread();
  if (bitmapReference!= null && bitmapReference.get()!= null) {
    return new ListenableFutureTask<>(bitmapReference.get());
  } else if (task!= null) {
    return task;
  } else {
    Callable<Bitmap> callable = new Callable<Bitmap>() {
      @Override public Bitmap call() throws Exception {
        try {
          Log.w(TAG, "loading page " + model.getSprite());
          return loadPage();
        } catch (IOException ioe) {
          Log.w(TAG, ioe);
        }
        return null;
      }
    };
    task = new ListenableFutureTask<>(callable);
    task.addListener(new FutureTaskListener<Bitmap>() {
      @Override public void onSuccess(final Bitmap result) {
        bitmapReference = new SoftReference<>(result);
        task = null;
      }
      @Override public void onFailure(Throwable error) {
        Log.w(TAG, error);
        task = null;
      }
    });
    return task;
  }
}

