    public void handler(int pc,/*unsinged*/ int[] lo) {
        /*unsigned*/
        int i = 0;
        /*unsigned*/
        int b = lo[0];
        switch (pc & 0x09) {
            case 0x00:
                /* A */
                i = b;
                break;
            case 0x01:
                /* B */
                i = b & 0x03;
                i += ((b & 0x80) >> 1);
                i += ((b & 0x60) >> 3);
                i += ((~b) & 0x10);
                i += ((b & 0x08) << 2);
                i += ((b & 0x04) << 5);
                i &= 0xFF;
                break;
            case 0x08:
                /* D */
                i = b & 0x23;
                i += ((b & 0xC0) >> 4);
                i += ((b & 0x10) << 2);
                i += ((b & 0x08) << 1);
                i += (((~b) & 0x04) << 5);
                i &= 0xFF;
                break;
            case 0x09:
                /* C */
                i = b & 0x03;
                i += ((b & 0x80) >> 4);
                i += (((~b) & 0x40) >> 1);
                i += ((b & 0x20) >> 1);
                i += ((b & 0x10) >> 2);
                i += ((b & 0x08) << 3);
                i += ((b & 0x04) << 5);
                i &= 0xFF;
                break;
        }
        lo[0] = i;
    }
};

