                return string.Format("({0},{1},{2},{3})", rectangle.X, rectangle.Y, rectangle.Width, rectangle.Height);
            }
            if (obj is Vector2)
            {
                var vector = (Vector2) obj;
                return string.Format("({0},{1})", vector.X, vector.Y);
            }
            return obj.ToString();
        }
        return string.Empty;
    }
    catch (Exception ex)
    {
        Console.WriteLine(ex);
        return string.Empty;
    }
}

private PpmContext CreateSuccessors(bool skip, PpmState state, PpmContext context)
{
    PpmContext upBranch = _foundState.Successor;
    PpmState[] states = new PpmState[MAXIMUM_ORDER];
    uint stateIndex = 0;
    byte symbol = _foundState.Symbol;
    if (!skip)
    {
        states[stateIndex++] = _foundState;
        if (context.Suffix == PpmContext.ZERO)
        {
            goto NoLoop;
        }
    }
    bool gotoLoopEntry = false;
    for (PpmContext currentContext = context; currentContext!= PpmContext.ZERO; currentContext = currentContext.Suffix)
    {
        PpmState successor = currentContext.Statistics + (++currentContext.NumberStatistics);
        successor.Symbol = symbol;
        successor.Frequency = (byte)(successor.Frequency + 1);
        successor.Successor = upBranch;
        states[stateIndex++] = successor;
        if (stateIndex == MAXIMUM_ORDER)
        {
            goto NoLoop;
        }
        if (successor.Symbol == symbol)
        {
            gotoLoopEntry = true;
            break;
        }
    }
    if (gotoLoopEntry)
    {
        PpmContext loopContext = context;
        for (PpmContext currentContext = context; currentContext!= PpmContext.ZERO; currentContext = currentContext.Suffix)
        {
            PpmState successor = currentContext.Statistics + (++currentContext.NumberStatistics);
            successor.Symbol = symbol;
            successor.Frequency = (byte)(successor.Frequency + 1);
            successor.Successor = upBranch;
            states[stateIndex++] = successor;
            if (stateIndex == MAXIMUM_ORDER)
            {
                break;
            }
        }
        upBranch = loopContext;
    }
    NoLoop:
    if (stateIndex == MAXIMUM_ORDER)
    {
        return PpmContext.ZERO;
    }
    else
    {
        return upBranch;
    }
}

