class endpoint_key_list(XDRStruct):
    __slots__ = ['keys']
    def __init__(self, keys=None):
        self.keys = keys
    @classmethod
    def pack_into(self, packer, obj):
        packer.pack_int(len(obj.keys))
        for key in obj.keys:
            key.pack_into(packer, key)
    @classmethod
    def unpack_from(cls, unpacker):
        length = unpacker.unpack_int()
        keys = []
        for _ in range(length):
            key = endpoint_key.unpack_from(unpacker)
            keys.append(key)
        return cls(keys=keys)
    def __eq__(self, other):
        if type(self)!= type(other):
            return False
        if self.keys!= other.keys:
            return False
        return True
    def __repr__(self):
        parts = []
        parts.append('endpoint_key_list(')
        parts.append('keys=[')
        for key in self.keys:
            parts.append(repr(key))
            parts.append(', ')
        parts.append('])')
        return ''.join(parts)

