            break;
        case ColumnType.TIMESTAMP:
            DateLocale timestampLocale =
                    locale == null?
                            this.dateLocale
                            : dateLocaleFactory.getLocale(locale);
            if (timestampLocale == null) {
                throw JsonException.$(localePosition, "Invalid timestamp locale");
            }
            // timestamp pattern is required
            if (pattern == null) {
                throw JsonException.$(0, "TIMESTAMP format pattern is required");
            }
            columnTypes.add(typeManager.nextTimestampAdapter().of(timestampFormatFactory.get(pattern), timestampLocale));
            break;
        case ColumnType.STRING:
            if (utf8) {
                columnTypes.add(typeManager.nextUtf8StringAdapter());
            } else {
                columnTypes.add(typeManager.nextStringAdapter());
            }
            break;
        case ColumnType.BINARY:
            if (utf8) {
                columnTypes.add(typeManager.nextUtf8BinaryAdapter());
            } else {
                columnTypes.add(typeManager.nextBinaryAdapter());
            }
            break;
        case ColumnType.INTEGER:
            if (index) {
                columnTypes.add(typeManager.nextIndexAdapter());
            } else {
                columnTypes.add(typeManager.nextIntegerAdapter());
            }
            break;
        default:
            throw JsonException.$(position, "Unsupported type");
    }
}

