            data_encipherment=current_key_usage == OpenSSL.crypto.X509v3ExtKeyUsage.data_encipherment,
            key_agreement=current_key_usage == OpenSSL.crypto.X509v3ExtKeyUsage.key_agreement,
            key_cert_sign=current_key_usage == OpenSSL.crypto.X509v3ExtKeyUsage.key_cert_sign,
            crl_sign=current_key_usage == OpenSSL.crypto.X509v3ExtKeyUsage.crl_sign,
            encipher_only=False,
            decipher_only=False,
        )
        if key_usage['key_agreement']:
            key_usage.update(dict(
                encipher_only=current_key_usage == OpenSSL.crypto.X509v3ExtKeyUsage.encipher_only,
