def _get_extended_key_usage(self):
    try:
        ext_keyusage_ext = self.cert.get_extension(OpenSSL.crypto.X509v3ExtExtendedKeyUsage)
        return sorted([
            crypto_utils.pyopenssl_normalize_name(eku) for eku in ext_keyusage_ext.get_short_name().split(',')
        ]), ext_keyusage_ext.critical
    except OpenSSL.crypto.Error:
        return None, False

def _get_basic_constraints(self):
    try:
        ext_keyusage_ext = self.cert.get_extension(OpenSSL.crypto.X509v3ExtBasicConstraints)
        result = []
        result.append('CA:{0}'.format('TRUE' if ext_keyusage_ext.get_critical() else 'FALSE'))
        if ext_keyusage_ext.get_subject_key_identifier():
            result.append('pathlen:{0}'.format(ext_keyusage_ext.get_path_length()))
        return sorted(result), ext_keyusage_ext.get_critical()
    except OpenSSL.crypto.Error:
        return None, False

def _get_ocsp_must_staple(self):
    try:
        try:
            # This only works with pyOpenSSL >= 0.15.1
            tlsfeature_ext = self.cert.get_extension(OpenSSL.crypto.X509v3ExtTLSFeature)
            value = tlsfeature_ext.get_short_name() == OpenSSL.crypto.X509v3ExtTLSFeature.status_request
        except AttributeError as dummy:
            # Fallback for pyOpenSSL < 0.15.1
            oid = OpenSSL.crypto.X509ExtensionOID.TLS_FEATURE
            tlsfeature_ext = self.cert.get_extension(oid)
            value = tlsfeature_ext.get_short_name() == OpenSSL.crypto.X509ExtensionOID.TLS_FEATURE_STATUS_REQUEST
        return value, tlsfeature_ext.get_critical()
    except OpenSSL.crypto.Error:
        return None, False

def _get_subject_alt_name(self):
    try:
        san_ext = self.cert.get_extension(OpenSSL.crypto.X509v3ExtSubjectAlternativeName)
        result = [crypto_utils.pyopenssl_decode_name(san) for san in san_ext.get_short_name().split(',')]
        return result, san_ext.get_critical()
    except OpenSSL.crypto.Error:
        return None, False

def _get_not_before(self):
