public static boolean existsInducingPathInto(Node x, Node y, Graph graph) {
    if (x.getNodeType()!= NodeType.MEASURED) throw new IllegalArgumentException();
    if (y.getNodeType()!= NodeType.MEASURED) throw new IllegalArgumentException();
    final LinkedList<Node> path = new LinkedList<>();
    path.add(x);
    return collectInducedNodesVisit2(graph, x, y, path);
}

public static boolean collectInducedNodesVisit2(Graph graph, Node x, Node y, LinkedList<Node> path) {
    if (path.contains(y)) {
        return true;
    }
    path.addLast(y);
    for (Node z : graph.getAdjacentNodes(y)) {
        if (z.getNodeType() == NodeType.MEASURED) {
            if (path.size() >= 2) {
                Node _a = path.get(path.size() - 2);
                Node _b = path.get(path.size() - 1);
                if (graph.isDefCollider(_a, _b, z)) {
                    if (!(graph.isAncestorOf(_b, x) || graph.isAncestorOf(_b, y))) {
                        path.removeLast();
                        return false;
                    }
                }
            }
            if (collectInducedNodesVisit2(graph, x, z, path)) {
                return true;
            }
        }
    }
    path.removeLast();
    return false;
}

